local MaceAxeMaker = {}
local PRODUCTS = {
    wooden_club = { name = "Lesena kijača", woodCost = 2, time = 1, cost = 12, attack = 5, durability = 18, description = "Preprosta lesena kijača za kmete." },
    iron_mace = { name = "Železen buzdovan", ironCost = 2, woodCost = 1, time = 3, cost = 50, attack = 10, durability = 30, prestige = 1, description = "Železen buzdovan z gumbi." },
    battle_axe = { name = "Bojna sekira", ironCost = 2, steelCost = 1, woodCost = 1, time = 5, cost = 140, attack = 16, durability = 38, prestige = 3, happiness = 1, description = "Bojna sekira z dvojnim rezom." },
    flanged_mace = { name = "Robnik buzdovan", steelCost = 2, ironCost = 1, woodCost = 1, time = 7, cost = 320, attack = 22, durability = 50, prestige = 6, happiness = 2, description = "Robnik buzdovan za prebijanje oklepov." },
    silver_war_hammer = { name = "Srebrni bojni kladivec", steelCost = 2, silverCost = 1, woodCost = 1, time = 9, cost = 720, attack = 28, durability = 60, prestige = 13, happiness = 3, description = "Bojni kladivec s srebrnim okrasjem." },
    royal_ceremonial_mace = { name = "Kraljevski slovesni buzdovan", steelCost = 3, goldCost = 2, silverCost = 1, jewelCost = 2, pearlCost = 1, woodCost = 1, time = 14, cost = 2200, attack = 42, durability = 85, prestige = 55, happiness = 11, description = "Veliki kraljevski slovesni buzdovan z zlatim, draguljnim in bisernim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Buzdovanska delavnica", cost = { gold = 270, wood = 130 }, upkeep = 6, qualityBonus = 5 },
    forge = { name = "Buzdovanska kovačija", cost = { gold = 850, wood = 220, stone = 200, iron = 8 }, upkeep = 20, qualityBonus = 18 },
    finishing_room = { name = "Dokončevalnica", cost = { gold = 1800, wood = 280, stone = 400, silver = 25, steel = 8 }, upkeep = 42, qualityBonus = 30 },
    royal_mace_atelier = { name = "Kraljevski atelje buzdovanov", cost = { gold = 7000, wood = 500, stone = 700, gold = 50, jewel = 20 }, upkeep = 130, qualityBonus = 55, prestigeBonus = 30 },
}
MaceAxeMaker.woodStock = 14; MaceAxeMaker.ironStock = 12; MaceAxeMaker.steelStock = 10; MaceAxeMaker.silverStock = 6; MaceAxeMaker.goldStock = 6; MaceAxeMaker.jewelStock = 6; MaceAxeMaker.pearlStock = 4
MaceAxeMaker.productStock = {}; MaceAxeMaker.buildings = {}; MaceAxeMaker.maker = nil; MaceAxeMaker.activeMaking = {}; MaceAxeMaker.totalProducts = 0; MaceAxeMaker.dayTimer = 0
function MaceAxeMaker.init() MaceAxeMaker.woodStock=14; MaceAxeMaker.ironStock=12; MaceAxeMaker.steelStock=10; MaceAxeMaker.silverStock=6; MaceAxeMaker.goldStock=6; MaceAxeMaker.jewelStock=6; MaceAxeMaker.pearlStock=4; MaceAxeMaker.productStock={}; MaceAxeMaker.buildings={}; MaceAxeMaker.maker=nil; MaceAxeMaker.activeMaking={}; MaceAxeMaker.totalProducts=0; MaceAxeMaker.dayTimer=0; print("[MaceAxeMaker] Royal Mace & Axe Maker System initialized (6 products, 4 buildings)") end
function MaceAxeMaker.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MaceAxeMaker.maker={name=n or ("Buzdovandži "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Buzdovandži najet: %s (spretnost: %d)",MaceAxeMaker.maker.name,s),"success") end; return true end
function MaceAxeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MaceAxeMaker.build(id) local ok,e=MaceAxeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MaceAxeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MaceAxeMaker.getQualityBonus() local b=0; for _,bd in ipairs(MaceAxeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MaceAxeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and MaceAxeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and MaceAxeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and MaceAxeMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.silverCost and MaceAxeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MaceAxeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MaceAxeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MaceAxeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MaceAxeMaker.buildings==0 then return false,"Potrebna delavnica" end; if not MaceAxeMaker.maker then return false,"Potreben buzdovandži" end; return true end
function MaceAxeMaker.make(pt,qty) qty=qty or 1; local ok,e=MaceAxeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then MaceAxeMaker.woodStock=MaceAxeMaker.woodStock-d.woodCost*qty end; if d.ironCost then MaceAxeMaker.ironStock=MaceAxeMaker.ironStock-d.ironCost*qty end; if d.steelCost then MaceAxeMaker.steelStock=MaceAxeMaker.steelStock-d.steelCost*qty end; if d.silverCost then MaceAxeMaker.silverStock=MaceAxeMaker.silverStock-d.silverCost*qty end; if d.goldCost then MaceAxeMaker.goldStock=MaceAxeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MaceAxeMaker.jewelStock=MaceAxeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MaceAxeMaker.pearlStock=MaceAxeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MaceAxeMaker.maker then t=math.max(1,t-math.floor(MaceAxeMaker.maker.skill/12)) end; table.insert(MaceAxeMaker.activeMaking,{id="mace_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MaceAxeMaker.completeMaking(m) local q=1.0+(MaceAxeMaker.getQualityBonus()/100); if MaceAxeMaker.maker then q=q+(MaceAxeMaker.maker.skill/180) end; q=math.min(2.0,q); MaceAxeMaker.productStock[m.productType]=(MaceAxeMaker.productStock[m.productType] or 0)+m.quantity; MaceAxeMaker.totalProducts=MaceAxeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MaceAxeMaker.maker then MaceAxeMaker.maker.itemsMade=MaceAxeMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then MaceAxeMaker.maker.skill=math.min(100,MaceAxeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Buzdovan izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"mace.completed",{productName=m.productName,attack=m.attack,durability=m.durability}) end end
function MaceAxeMaker.update(dt) if not _G.state then return end; MaceAxeMaker.dayTimer=MaceAxeMaker.dayTimer+dt; if MaceAxeMaker.dayTimer>=30 then MaceAxeMaker.dayTimer=0; for i=#MaceAxeMaker.activeMaking,1,-1 do local m=MaceAxeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MaceAxeMaker.completeMaking(m); table.remove(MaceAxeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MaceAxeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MaceAxeMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MaceAxeMaker.getStats() return {woodStock=MaceAxeMaker.woodStock,ironStock=MaceAxeMaker.ironStock,steelStock=MaceAxeMaker.steelStock,silverStock=MaceAxeMaker.silverStock,goldStock=MaceAxeMaker.goldStock,jewelStock=MaceAxeMaker.jewelStock,pearlStock=MaceAxeMaker.pearlStock,productStock=MaceAxeMaker.productStock,numBuildings=#MaceAxeMaker.buildings,hasMaker=MaceAxeMaker.maker~=nil,makerName=MaceAxeMaker.maker and MaceAxeMaker.maker.name or "—",makerSkill=MaceAxeMaker.maker and MaceAxeMaker.maker.skill or 0,activeMaking=#MaceAxeMaker.activeMaking,totalProducts=MaceAxeMaker.totalProducts} end
return MaceAxeMaker
